#include <stdio.h>

/* teste do desafio triangulo-de-hashtags — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen) e captura o stdout no proprio teste.
   Os nomes dos arquivos temporarios sao POR CENARIO: um cenario nunca le a
   entrada nem a captura do outro. Nunca ha fclose de stdin/stdout — so
   fflush — para o segundo freopen ficar legal (C11 7.21.4).
   Os dois N sao diferentes de proposito, e as linhas do cenario de N=4 tem
   tamanhos diferentes entre si: um desenho escrito a mao no codigo nao
   passa nos dois cenarios. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void trianguloDeHashtags(void);

SM_TEST(o_triangulo_de_4_linhas) {
    /* o que a pessoa digita: 4 */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "4\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    /* captura: o stdout vira o arquivo sm_saida_1.tmp */
    freopen("sm_saida_1.tmp", "w", stdout);
    trianguloDeHashtags();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("linha 1 de N=4", linha, "#\n",
              "a linha 1 do triangulo tem 1 marca(s)");
    fgets(linha, 80, f);
    checa_str("linha 2 de N=4", linha, "##\n",
              "a linha 2 do triangulo tem 2 marca(s)");
    fgets(linha, 80, f);
    checa_str("linha 3 de N=4", linha, "###\n",
              "a linha 3 do triangulo tem 3 marca(s)");
    fgets(linha, 80, f);
    checa_str("linha 4 de N=4", linha, "####\n",
              "a linha 4 do triangulo tem 4 marca(s)");

    /* a saida TERMINA na linha 4 — buffer novo com sentinel */
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais em N=4", fim, "(nada impresso)",
              "com N=4 o triangulo acaba na quarta linha: nenhuma linha extra e aceita");
    fclose(f);
}

