#include <stdio.h>

void trianguloDeHashtags(void) {
    int n = 0;
    scanf("%d", &n);

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            printf("#");
        }

        printf("\n");
    }
}
